using System.Text;

namespace Cs2Ts.DataGen;

/// <summary>
/// Turns a surface into the two files that describe it: the class the plugin binds and
/// the interface an author's editor reads.
///
/// They are written together, from one model, because the failure this replaces is the
/// two drifting apart — a declaration for a field the runtime does not have is worse
/// than no declaration, and a field with no declaration cannot be typed at all.
/// </summary>
internal static class Emit
{
    private const string Warning =
        "// <auto-generated>\n" +
        "//     Written by tools/datagen from CounterStrikeSharp's own classes. Do not edit.\n" +
        "//     Regenerate with: dotnet run --project tools/datagen\n" +
        "// </auto-generated>\n" +
        "\n" +
        // The auto-generated header opts these files out of the project's nullable
        // context, and the compiler then warns on every annotation in them. Turning it
        // back on is the whole fix: a nullable player field has to be able to say so.
        "#nullable enable";

    /// <summary>
    /// Every entity surface in one file: the class the plugin binds for each of
    /// CounterStrikeSharp's entity classes, in a tree that mirrors the game's own.
    ///
    /// One file rather than one per class, for the reason the events are one file — five
    /// hundred files is five hundred things a reviewer pages past, and none of it is read
    /// by hand.
    /// </summary>
    public static string CSharpFile(IReadOnlyList<SchemaSurface> surfaces)
    {
        var text = new StringBuilder();

        text.AppendLine(Warning);
        text.AppendLine();
        text.AppendLine("using System.Globalization;");
        text.AppendLine("using Cs2Ts.Runtime;");
        text.AppendLine("using Microsoft.ClearScript;");
        text.AppendLine();
        text.AppendLine("namespace Cs2Ts.Plugin;");

        foreach (var surface in surfaces)
        {
            text.AppendLine();
            text.Append(CSharp(surface));
        }

        return text.ToString();
    }

    /// <summary>One surface's class, without the file's header — the unit the tests check.</summary>
    public static string CSharp(SchemaSurface surface)
    {
        var entity = Surfaces.FullName(surface.Entity);
        var root = surface.BaseName is null;
        var text = new StringBuilder();

        text.AppendLine("/// <summary>");
        text.AppendLine(root
            ? $"/// Every field a {surface.Entity.Name} has, as script reaches it through <c>entity.raw</c>."
            : $"/// The fields a {surface.Entity.Name} adds to {surface.Entity.BaseType!.Name}.");
        text.AppendLine("///");
        text.AppendLine("/// One member per schema field, each one named as the schema names it and each one");
        text.AppendLine("/// re-resolving the entity rather than holding it. Writes are replicated: see");
        text.AppendLine("/// <see cref=\"SchemaWrite\"/> for the half of a write that is invisible when it is missing.");
        text.AppendLine("///");
        text.AppendLine("/// The class per entity, deriving the same way the game's classes do, so the whole set");
        text.AppendLine("/// stays a few thousand members rather than the tens of thousands a flat class each");
        text.AppendLine("/// would be. An explicit constructor rather than a primary one only because the shared");
        text.AppendLine("/// state is both kept and handed to the base, which a primary constructor warns on.");
        text.AppendLine("/// </summary>");
        text.AppendLine("[DefaultScriptUsage(ScriptAccess.None)]");
        text.AppendLine($"public class {surface.Name} : {(root ? "ScriptSurface" : surface.BaseName)}");
        text.AppendLine("{");

        var hasResolve = surface.Fields.Count > 0;

        if (hasResolve)
        {
            text.AppendLine($"    private readonly Func<{entity}> _resolve;");
        }

        if (root)
        {
            if (hasResolve)
            {
                text.AppendLine();
            }

            text.AppendLine("    /// <summary>");
            text.AppendLine("    /// The one entity table for the server. A field that holds another entity turns");
            text.AppendLine("    /// into one through here, so the same entity reached two ways is one object.");
            text.AppendLine("    /// </summary>");
            text.AppendLine("    private protected readonly CssEntities _entities;");
        }

        if (hasResolve || root)
        {
            text.AppendLine();
        }

        text.AppendLine("    /// <param name=\"resolve\">");
        text.AppendLine("    /// The live entity, re-read on every access and never held. It throws rather than");
        text.AppendLine("    /// returning something stale once the entity is gone.");
        text.AppendLine("    /// </param>");
        text.AppendLine("    /// <param name=\"entities\">The server's one entity table, for fields that hold another entity.</param>");

        if (root)
        {
            text.AppendLine($"    public {surface.Name}(Func<{entity}> resolve, CssEntities entities)");
            text.AppendLine("    {");
            text.AppendLine("        _resolve = resolve;");
            text.AppendLine("        _entities = entities;");
            text.AppendLine("    }");
        }
        else if (hasResolve)
        {
            text.AppendLine(
                $"    public {surface.Name}(Func<{entity}> resolve, CssEntities entities) : base(resolve, entities) =>");
            text.AppendLine("        _resolve = resolve;");
        }
        else
        {
            text.AppendLine(
                $"    public {surface.Name}(Func<{entity}> resolve, CssEntities entities) : base(resolve, entities)");
            text.AppendLine("    {");
            text.AppendLine("    }");
        }

        foreach (var field in surface.Fields)
        {
            var read = string.Format(field.ReadFormat, $"_resolve().{field.ClrName}");
            var modifier = field.Shadows ? "new " : "";

            text.AppendLine();
            text.AppendLine($"    /// <summary>{field.ClassName}/{field.FieldName}{Sentence(field.Note)}</summary>");
            text.AppendLine($"    [ScriptMember(\"{field.ScriptName}\")]");

            if (field.WriteFormat is null)
            {
                text.AppendLine($"    public {modifier}{field.CSharpType} {field.ClrName} => {read};");
            }
            else
            {
                text.AppendLine($"    public {modifier}{field.CSharpType} {field.ClrName}");
                text.AppendLine("    {");
                text.AppendLine($"        get => {read};");
                text.AppendLine("        set");
                text.AppendLine("        {");
                text.AppendLine("            var entity = _resolve();");
                text.AppendLine($"            SchemaWrite.Replicate(entity, \"{field.ClassName}\", \"{field.FieldName}\",");
                text.AppendLine($"                () => entity.{field.ClrName} = {field.WriteFormat});");
                text.AppendLine("        }");
                text.AppendLine("    }");
            }
        }

        text.AppendLine("}");
        return text.ToString();
    }

    /// <summary>
    /// The declarations for one surface, indented to sit inside the region the shipped
    /// declaration file keeps for them.
    /// </summary>
    public static string TypeScript(SchemaSurface surface)
    {
        var text = new StringBuilder();
        var fields = surface.Flat ? surface.AllFields : surface.Fields;
        var extends = surface.BaseName is null || surface.Flat ? "" : $" extends {surface.BaseName}";
        var heading = surface.Flat
            ? $"Every field a {surface.Entity.Name} has, by name. Flattened: it reuses a base field's name for a different type."
            : surface.BaseName is null
                ? $"Every field a {surface.Entity.Name} has, by name."
                : $"The fields a {surface.Entity.Name} adds to {surface.BaseName}.";

        text.AppendLine($"    /** {heading} */");
        text.AppendLine($"    interface {surface.Name}{extends} {{");

        foreach (var field in fields)
        {
            var modifier = field.WriteFormat is null ? "readonly " : "";
            text.AppendLine($"        /** {field.ClassName}/{field.FieldName}{Sentence(field.Note)} */");
            text.AppendLine($"        {modifier}{field.ScriptName}: {field.TypeScriptType};");
        }

        text.AppendLine("    }");
        return text.ToString();
    }

    /// <summary>
    /// The map from a schema class name to the surface for it, as the class the plugin
    /// binds behind <c>entity.as</c>.
    ///
    /// A dictionary of tiny factories rather than a switch: the switch the events use was
    /// measured at 890 ms to compile on its first call, and this is twice the size. Each
    /// factory re-wraps the generic entity resolver as its own type — the surfaces take a
    /// typed <c>Func</c>, and the one the facade holds is <c>Func&lt;CBaseEntity&gt;</c>.
    /// </summary>
    public static string CSharpFactory(IReadOnlyList<SchemaSurface> surfaces)
    {
        var baseEntity = Surfaces.FullName(typeof(CounterStrikeSharp.API.Core.CBaseEntity));
        var text = new StringBuilder();

        text.AppendLine(Warning);
        text.AppendLine();
        text.AppendLine("using Cs2Ts.Runtime;");
        text.AppendLine("using Microsoft.ClearScript;");
        text.AppendLine();
        text.AppendLine("namespace Cs2Ts.Plugin;");
        text.AppendLine();
        text.AppendLine("/// <summary>");
        text.AppendLine("/// The wide surface for an entity of a named schema class, behind <c>entity.as</c>.");
        text.AppendLine("///");
        text.AppendLine("/// <c>as</c> is an assertion by the script that the entity is of that class, checked no");
        text.AppendLine("/// more than <c>unsafe</c> checks its class argument and typed where <c>unsafe</c> is");
        text.AppendLine("/// not. A name the game does not bind is refused; a name it binds for an entity that is");
        text.AppendLine("/// something else reads the wrong fields' bytes rather than throwing.");
        text.AppendLine("/// </summary>");
        text.AppendLine("internal static class EntitySurfaces");
        text.AppendLine("{");
        text.AppendLine(
            $"    private static readonly Dictionary<string, Func<Func<{baseEntity}>, CssEntities, ScriptSurface>> Factories =");
        text.AppendLine("        new(StringComparer.Ordinal)");
        text.AppendLine("    {");

        foreach (var surface in surfaces)
        {
            var entity = Surfaces.FullName(surface.Entity);
            var resolver = surface.BaseName is null
                ? "resolve"
                : $"() => new {entity}(resolve().Handle)";

            text.AppendLine($"        [\"{surface.Entity.Name}\"] = (resolve, entities) => new {surface.Name}({resolver}, entities),");
        }

        text.AppendLine("    };");
        text.AppendLine();
        text.AppendLine("    /// <summary>The schema class names <c>as</c> accepts, for the error when it is given another.</summary>");
        text.AppendLine("    public static IReadOnlyCollection<string> Names => Factories.Keys;");
        text.AppendLine();
        text.AppendLine("    /// <summary>");
        text.AppendLine("    /// The surface for one schema class, or a throw naming the mistake.");
        text.AppendLine("    /// </summary>");
        text.AppendLine("    /// <param name=\"schemaClass\">The class name, spelled as the schema spells it.</param>");
        text.AppendLine("    /// <param name=\"resolve\">The generic entity resolver the facade holds.</param>");
        text.AppendLine("    /// <param name=\"entities\">The server's one entity table.</param>");
        text.AppendLine($"    public static ScriptSurface For(string schemaClass, Func<{baseEntity}> resolve, CssEntities entities)");
        text.AppendLine("    {");
        text.AppendLine("        ArgumentException.ThrowIfNullOrEmpty(schemaClass);");
        text.AppendLine("        return Factories.TryGetValue(schemaClass, out var make)");
        text.AppendLine("            ? make(resolve, entities)");
        text.AppendLine("            : throw new ArgumentException(");
        text.AppendLine("                $\"there is no entity surface for a schema class called '{schemaClass}'; it has to be \" +");
        text.AppendLine("                \"one CounterStrikeSharp binds, spelled as the schema spells it — 'CAK47', 'CBaseDoor'\");");
        text.AppendLine("    }");
        text.AppendLine();
        text.AppendLine("    /// <summary>");
        text.AppendLine("    /// Builds the table now, at plugin load, so that the first <c>as</c> in a script does");
        text.AppendLine("    /// not pay to compile the initializer against the watchdog's budget — the trap the");
        text.AppendLine("    /// event switch has.");
        text.AppendLine("    /// </summary>");
        text.AppendLine("    public static void Warm() => _ = Factories.Count;");
        text.AppendLine("}");

        return text.ToString();
    }

    /// <summary>
    /// The declarations counterpart of <see cref="CSharpFactory"/>: the map an author's
    /// editor uses to give <c>entity.as("CAK47")</c> the type <c>CAK47Raw</c>.
    /// </summary>
    public static string TypeScriptSchemaClasses(IReadOnlyList<SchemaSurface> surfaces)
    {
        var text = new StringBuilder();

        text.AppendLine("    /** Every schema class `entity.as` accepts, and the surface each one gives. */");
        text.AppendLine("    interface EntitySchemaClasses {");

        foreach (var surface in surfaces)
        {
            text.AppendLine($"        \"{surface.Entity.Name}\": {surface.Name};");
        }

        text.AppendLine("    }");
        return text.ToString();
    }

    /// <summary>
    /// Every event, as the classes the plugin hands to script and the switch that hooks
    /// them.
    ///
    /// One file rather than one per event, because nothing here is read by hand and two
    /// hundred and seventy files would be two hundred and seventy things a reviewer has
    /// to page past.
    /// </summary>
    public static string CSharpEvents(IReadOnlyList<EventSurface> surfaces)
    {
        var text = new StringBuilder();

        text.AppendLine(Warning);
        text.AppendLine();
        text.AppendLine("using System.Globalization;");
        text.AppendLine("using CounterStrikeSharp.API.Core;");
        text.AppendLine("using Cs2Ts.Runtime;");
        text.AppendLine("using Microsoft.ClearScript;");
        text.AppendLine();
        text.AppendLine("// Aliased rather than spelled out: the facade's two type arguments would otherwise");
        text.AppendLine("// appear on every player field of every event.");
        text.AppendLine($"using PlayerRef = {Facade};");
        text.AppendLine($"using PlayerTable = {Table};");
        text.AppendLine();
        text.AppendLine("namespace Cs2Ts.Plugin;");

        foreach (var surface in surfaces)
        {
            var entity = Surfaces.FullName(surface.Event);

            text.AppendLine();
            text.AppendLine("/// <summary>");
            text.AppendLine($"/// The <c>{surface.GameName}</c> event, copied out.");
            text.AppendLine("///");
            text.AppendLine("/// A snapshot rather than a view. The event itself belongs to the callback it");
            text.AppendLine("/// arrived in, so every value is read while it is still there and every player");
            text.AppendLine("/// becomes a facade — an identity that is still meaningful in a timer five seconds");
            text.AppendLine("/// later, which is where a script is likely to look at it.");
            text.AppendLine("/// </summary>");
            text.AppendLine("[DefaultScriptUsage(ScriptAccess.None)]");
            text.AppendLine($"public sealed class {surface.PayloadName} : ScriptSurface");
            text.AppendLine("{");
            text.AppendLine($"    internal {surface.PayloadName}({entity} @event, PlayerTable? players)");
            text.AppendLine("    {");

            if (surface.Fields.Count == 0)
            {
                text.AppendLine("        // This event carries nothing; it is the fact that it happened.");
            }

            foreach (var field in surface.Fields)
            {
                var read = string.Format(field.ReadFormat, $"@event.{field.ClrName}");
                text.AppendLine($"        {Pascal(field.ScriptName)} = {read};");
            }

            text.AppendLine("    }");

            foreach (var field in surface.Fields)
            {
                text.AppendLine();
                text.AppendLine($"    /// <summary>{surface.Event.Name}.{field.ClrName}{Sentence(field.Note)}</summary>");
                text.AppendLine($"    [ScriptMember(\"{field.ScriptName}\")]");
                text.AppendLine($"    public {field.CSharpType} {Pascal(field.ScriptName)} {{ get; }}");
            }

            text.AppendLine("}");
        }

        text.AppendLine();
        text.AppendLine("public sealed partial class Cs2TsPlugin");
        text.AppendLine("{");
        text.AppendLine("    /// <summary>");
        text.AppendLine("    /// Hooks one game event with the server, the first time a script asks for it.");
        text.AppendLine("    ///");
        text.AppendLine("    /// Nothing is hooked in advance. A script that listens for three events pays for");
        text.AppendLine("    /// three, and the rest of the game's events never reach this plugin at all.");
        text.AppendLine("    ///");
        text.AppendLine("    /// One method per event rather than one body with every registration in it, and");
        text.AppendLine("    /// that is not tidiness. The single-method version was measured on a server at");
        text.AppendLine("    /// 800 ms for the first hook and under 2 ms for every one after it: the whole");
        text.AppendLine("    /// method has to be compiled before any of it runs, and two hundred and seventy");
        text.AppendLine("    /// three generic registrations is a lot to compile. 800 ms is past the watchdog's");
        text.AppendLine("    /// budget, so the script that asked was killed mid-load. Split up, only the one");
        text.AppendLine("    /// method that is called gets compiled.");
        text.AppendLine("    /// </summary>");
        text.AppendLine("    /// <returns>Whether the name is a game event at all.</returns>");
        text.AppendLine("    private bool HookGameEvent(string name)");
        text.AppendLine("    {");
        text.AppendLine("        switch (name)");
        text.AppendLine("        {");

        foreach (var surface in surfaces.OrderBy(surface => surface.GameName, StringComparer.Ordinal))
        {
            text.AppendLine($"            case \"{surface.GameName}\": Hook{surface.PayloadName}(); return true;");
        }

        text.AppendLine("            default: return false;");
        text.AppendLine("        }");
        text.AppendLine("    }");

        foreach (var surface in surfaces.OrderBy(surface => surface.GameName, StringComparer.Ordinal))
        {
            var entity = Surfaces.FullName(surface.Event);

            text.AppendLine();
            text.AppendLine("    /// <summary>");
            text.AppendLine($"    /// Hooks <c>{surface.GameName}</c>. The listener check is what keeps a hook that");
            text.AppendLine("    /// outlived the script that wanted it from building a snapshot for nobody.");
            text.AppendLine("    /// </summary>");
            text.AppendLine($"    private void Hook{surface.PayloadName}() =>");
            text.AppendLine($"        RegisterEventHandler<{entity}>((@event, _) =>");
            text.AppendLine("        {");
            text.AppendLine($"            if (_host is {{ }} host && host.Handles(\"{surface.GameName}\"))");
            text.AppendLine("            {");
            text.AppendLine(
                $"                host.Dispatch(\"{surface.GameName}\", new {surface.PayloadName}(@event, _players));");
            text.AppendLine("            }");
            text.AppendLine();
            text.AppendLine("            return HookResult.Continue;");
            text.AppendLine("        });");
        }

        text.AppendLine("}");

        return text.ToString();
    }

    /// <summary>
    /// The declarations for the events: one interface each, and the map that gives
    /// <c>on</c> its names.
    ///
    /// The map is declared again rather than replacing what is written by hand.
    /// TypeScript merges two declarations of one interface, so <c>tick</c> — which is
    /// the runtime's own rather than the game's — stays where its explanation is.
    /// </summary>
    public static string TypeScriptEvents(IReadOnlyList<EventSurface> surfaces)
    {
        var text = new StringBuilder();

        foreach (var surface in surfaces)
        {
            text.AppendLine($"    /** What the <c>{surface.GameName}</c> event carries. */"
                .Replace("<c>", "`").Replace("</c>", "`"));
            text.AppendLine($"    interface {surface.PayloadName} {{");

            foreach (var field in surface.Fields)
            {
                text.AppendLine($"        /** {surface.Event.Name}.{field.ClrName}{Sentence(field.Note)} */");
                text.AppendLine($"        readonly {field.ScriptName}: {field.TypeScriptType};");
            }

            text.AppendLine("    }");
            text.AppendLine();
        }

        text.AppendLine("    interface Cs2TsEvents {");

        foreach (var surface in surfaces.OrderBy(surface => surface.GameName, StringComparer.Ordinal))
        {
            text.AppendLine($"        {surface.GameName}: (event: {surface.PayloadName}) => void;");
        }

        text.AppendLine("    }");
        return text.ToString();
    }

    private const string Facade =
        "Cs2Ts.Runtime.PlayerFacade<CounterStrikeSharp.API.Core.CCSPlayerController, " +
        "CounterStrikeSharp.API.Core.CCSPlayerPawn>";

    private const string Table =
        "Cs2Ts.Runtime.PlayerFacadeTable<CounterStrikeSharp.API.Core.CCSPlayerController, " +
        "CounterStrikeSharp.API.Core.CCSPlayerPawn>";

    private static string Pascal(string name) => char.ToUpperInvariant(name[0]) + name[1..];

    private static string Sentence(string? note) => note is null ? "" : $" — {note}";
}
